/* ==== js/desktop/screens/fallback.js ==== */
/* Desktop fallback — a mobile screen with no desktop design yet. Keeps the desktop
   shell (so the switch never dead-ends) and offers the mobile view of the same state.
   Prototype chrome, not product UI. */
(function () {
  const { html } = OPL;
  const D = OPL.d;
  // Which Loans tab / sidebar item a mobile screen belongs to
  const TAB = { "loan-offers": "offers", "compare-loans": "compare", applications: "applications", application: "applications", kfs: "applications", nesl: "applications" };

  OPL.dscreens.__missing = {
    title: "Not on desktop yet",
    figma: {},
    render(page) {
      const name = OPL.current();
      const mobile = OPL.screens[name];
      const subsidy = /^subsid/.test(name);
      page.innerHTML = D.shell({
        nav: subsidy ? "subsidies" : "loans", title: subsidy ? "Govt. subsidies" : "Loans", tab: subsidy ? null : TAB[name] || "overview",
        body: html`
          <div class="d-missing">
            <p class="d-missing__eyebrow">Prototype</p>
            <p class="d-missing__title">${mobile ? mobile.title : "This screen"} isn't designed for desktop yet</p>
            <p class="d-missing__body">The same state is available in the mobile view.</p>
            <div class="d-missing__actions">
              ${D.btn({ label: "Open in mobile view", style: "filled", size: "md", attrs: "data-to-mobile" })}
              ${D.btn({ label: "Back to Overview", style: "outlined", size: "md", goto: "loans-overview" })}
            </div>
          </div>`,
      });
      D.mountShell(page);
      page.querySelector("[data-to-mobile]").addEventListener("click", () => OPL.setDevice("mobile"));
    },
  };
})();

;

/* ==== js/desktop/screens/loans-overview.js ==== */
/* Desktop · Loans › Overview — Figma 476:200124.
   Behaviour layer (prototype): count-up limit, CMR gauge sweep, chip filters with an
   empty state, a Sort menu and live re-ordering (FLIP), Compare selection with a
   counter on the Compare tab, chart draw-in, hover/focus states throughout. */
(function () {
  const { html, raw } = OPL;
  const D = OPL.d;
  const data = () => OPL.ddata.loansOverview;

  const SORTS = {
    "Lowest interest": (a, b) => a.meta.rate - b.meta.rate,
    "Highest loan amount": (a, b) => b.meta.amount - a.meta.amount,
    "Lowest EMI": (a, b) => a.meta.emi - b.meta.emi,
    "Lowest processing fee": (a, b) => a.meta.fee - b.meta.fee,
  };
  const CHIP_TEST = {
    "Collateral-free": (m) => m.collateralFree,
    "Working Capital": (m) => m.workingCapital,
    "Term loan": (m) => m.term,
    "Fee under 1%": (m) => m.fee < 1,
  };

  const hero = (h) => html`
    <section class="d-hero" data-enter>
      <div class="d-hero__copy">
        <p class="d-hero__eyebrow">${h.eyebrow}</p>
        <p class="d-hero__amount" data-countup>${h.amount}</p>
      </div>
      <div class="d-hero__glass">
        <div class="d-hero__picks">
          ${h.picks.map((p) => html`
            <div class="d-pick">
              <span class="d-pick__icon">${D.icon(p.icon, 20)}</span>
              <div><p class="d-pick__label">${p.label}</p><p class="d-pick__value">${p.value}</p></div>
            </div>`)}
        </div>
        ${D.aiRow(h.ai, { cls: "d-ai--glass" })}
      </div>
    </section>`;

  const matchesHead = (m, st) => html`
    <div class="d-matches__head">
      ${D.sectionHead({ title: m.title, count: m.count, link: m.link, goto: "loan-offers" })}
      <div class="d-toolbar">
        <div class="d-toolbar__chips">${m.chips.map((c) => D.chip(c, { selected: st.chips.includes(c), attrs: `data-chip="${c}"` }))}</div>
        <div class="d-toolbar__right">
          <div class="d-menu-anchor">
            <button class="d-pill d-pill--sort" data-menu="sort" aria-haspopup="menu" aria-expanded="false">
              ${D.icon("list-arrow-down", 16)}<span class="d-pill__muted">${m.sort.label}</span><b>${st.sort}</b>${D.icon("chevron-muted", 14, "d-pill__chev")}
            </button>
            <div class="d-menu" role="menu" data-menu-for="sort">
              ${m.sortOptions.map((o) => html`<button class="d-menu__item ${o === st.sort ? "is-on" : ""}" role="menuitemradio" aria-checked="${o === st.sort}" data-sort="${o}">${o}${o === st.sort ? D.micon("check-circle-chip", 16) : ""}</button>`)}
            </div>
          </div>
          <button class="d-pill" data-goto="loan-offers" data-filters>${D.icon("filter", 16)}<span>Filters</span>${D.icon("chevron-muted", 14, "d-pill__chev")}</button>
        </div>
      </div>
    </div>`;

  const cardsFor = (m, st) => {
    const cmp = D.compare.get();
    // Order as drawn until the user picks a sort (the frame lists Citi · Axis · SBI under "Lowest interest")
    const list = m.cards.filter((c) => st.chips.every((ch) => CHIP_TEST[ch](c.meta)));
    if (st.sorted) list.sort(SORTS[st.sort]);
    if (!list.length) return html`
      <div class="d-empty">
        <p class="d-empty__title">${m.empty.title}</p>
        <p class="d-empty__body">${m.empty.body}</p>
        ${D.btn({ label: m.empty.cta, style: "outlined", size: "sm", attrs: "data-clear-chips" })}
      </div>`;
    return list.map((c) => D.offerCard(c, { compared: cmp.includes(c.compareId) }));
  };

  const debt = (d) => html`
    <section class="d-debt" data-enter>
      ${D.sectionHead({ title: d.title, link: d.link, goto: "my-loans" })}
      <div class="d-debt__tiles">
        ${d.tiles.map((t) => html`
          <div class="d-stat">
            ${t.tag ? html`<span class="d-stat__tag">${t.tag}</span>` : ""}
            <span class="d-stat__icon">${D.icon(t.icon, 20)}</span>
            <p class="d-stat__value">${t.value}</p>
            <p class="d-stat__label">${t.label}</p>
          </div>`)}
      </div>
      <div class="d-debt__row">
        <article class="d-panel d-trend">
          <div class="d-panel__title">${d.trend.title}<span class="d-cmr__info" tabindex="0">${D.icon("info-circle-duo", 20)}${D.tip(d.trend.info)}</span></div>
          <div class="d-trend__figure">
            <p class="d-trend__amount">${d.trend.amount}</p>
            <p class="d-trend__sub">${d.trend.sub}</p>
          </div>
          <div class="d-trend__chart">
            <div class="d-trend__graph" data-graph></div>
            <span class="d-trend__dot">${D.icon("graph-dot", 11)}</span>
          </div>
          <div class="d-trend__tip"><b>${d.trend.tip.value}</b><span>${d.trend.tip.month}</span></div>
        </article>
        <article class="d-panel d-emis">
          <div class="d-emis__head">
            <div class="d-panel__title">${d.termLoans.title}${D.count(d.termLoans.count)}</div>
            ${D.link(d.termLoans.link, "my-loans")}
          </div>
          <div class="d-emis__rows">
            ${d.termLoans.rows.map((r) => html`
              <button class="d-emi" data-goto="my-loans">
                <span class="d-emi__icon">${D.icon(r.icon, 20)}</span>
                <span class="d-emi__name"><b>${r.name}</b><small>${r.due}</small></span>
                <span class="d-emi__amt">${r.amount}</span>
              </button>`)}
          </div>
        </article>
      </div>
    </section>`;

  OPL.dscreens["loans-overview"] = {
    title: "Loans · Overview",
    figma: { frame: "476:200124" },
    st: { chips: [], sort: "Lowest interest" },

    render(page) {
      const d = data();
      const st = this.st;
      const cmpCount = D.compare.get().length;
      page.innerHTML = D.shell({
        nav: "loans", title: "Loans", tab: "overview", counts: { compare: cmpCount || null },
        body: html`
          <div class="d-ov">
            <div class="d-ov__top">
              ${hero(d.hero)}
              <div data-enter>${D.cmrCard(d.cmr)}</div>
            </div>
            <section class="d-matches" data-enter>
              ${matchesHead(d.matches, st)}
              <div class="d-cards" data-cards>${cardsFor(d.matches, st)}</div>
            </section>
            ${debt(d.debt)}
          </div>`,
      });
      D.mountShell(page);
      D.mountCompareBar(page);
      D.mountGauge(page);
      D.enter(page);
      const amt = page.querySelector("[data-countup]");
      if (amt && !D.motionOff()) D.countUp(amt);
      this.mountGraph(page);
      this.bind(page);
    },

    // Repayment chart: inline the Figma line graph and draw it in left → right
    mountGraph(page) {
      const host = page.querySelector("[data-graph]");
      if (!host) return;
      D.inlineSvg("line-graph").then((svg) => {
        host.innerHTML = svg;
        const chart = host.closest(".d-trend");
        if (D.motionOff()) return chart.classList.add("is-drawn");
        const io = new IntersectionObserver((es) => {
          if (es.some((e) => e.isIntersecting)) { chart.classList.add("is-drawn"); io.disconnect(); }
        }, { threshold: 0.4 });
        OPL.afterReveal(() => io.observe(chart));
      });
    },

    // Re-render only the cards (FLIP: cards glide to their new slots)
    refreshCards(page) {
      const box = page.querySelector("[data-cards]");
      const before = new Map([...box.querySelectorAll("[data-offer]")].map((el) => [el.dataset.offer, el.getBoundingClientRect()]));
      box.innerHTML = cardsFor(data().matches, this.st);
      if (D.motionOff()) return;
      box.querySelectorAll("[data-offer]").forEach((el, i) => {
        const b = before.get(el.dataset.offer);
        if (b) {
          const a = el.getBoundingClientRect();
          const s = parseFloat(getComputedStyle(page.closest(".device-wrap") || document.body).transform.split(",")[0]?.replace("matrix(", "")) || 1;
          const dx = (b.left - a.left) / s;
          if (dx) el.animate([{ transform: `translateX(${dx}px)` }, { transform: "none" }], { duration: 420, easing: "cubic-bezier(0.22, 1, 0.36, 1)" });
        } else {
          el.animate([{ opacity: 0, transform: "translateY(8px) scale(0.98)" }, { opacity: 1, transform: "none" }], { duration: 320, delay: i * 40, easing: "cubic-bezier(0.22, 1, 0.36, 1)", fill: "backwards" });
        }
      });
    },

    bind(page) {
      const st = this.st;
      const closeMenus = () => page.querySelectorAll(".d-menu.is-open").forEach((m) => {
        m.classList.remove("is-open");
        page.querySelector(`[data-menu="${m.dataset.menuFor}"]`)?.setAttribute("aria-expanded", "false");
      });

      page.addEventListener("click", (e) => {
        const chip = e.target.closest("[data-chip]");
        if (chip) {
          const c = chip.dataset.chip;
          st.chips = st.chips.includes(c) ? st.chips.filter((x) => x !== c) : [...st.chips, c];
          chip.classList.toggle("is-selected");
          chip.setAttribute("aria-pressed", st.chips.includes(c));
          return this.refreshCards(page);
        }
        if (e.target.closest("[data-clear-chips]")) {
          st.chips = [];
          page.querySelectorAll("[data-chip].is-selected").forEach((c) => { c.classList.remove("is-selected"); c.setAttribute("aria-pressed", "false"); });
          return this.refreshCards(page);
        }
        const menuBtn = e.target.closest("[data-menu]");
        if (menuBtn) {
          const menu = page.querySelector(`[data-menu-for="${menuBtn.dataset.menu}"]`);
          const open = !menu.classList.contains("is-open");
          closeMenus();
          menu.classList.toggle("is-open", open);
          menuBtn.setAttribute("aria-expanded", open);
          if (open) menu.querySelector(".is-on")?.focus({ preventScroll: true });
          return;
        }
        const sort = e.target.closest("[data-sort]");
        if (sort) {
          st.sort = sort.dataset.sort;
          st.sorted = true;
          page.querySelector(".d-pill--sort b").textContent = st.sort;
          page.querySelectorAll("[data-sort]").forEach((b) => {
            const on = b.dataset.sort === st.sort;
            b.classList.toggle("is-on", on);
            b.setAttribute("aria-checked", on);
            b.querySelector(".ico")?.remove();
            if (on) b.insertAdjacentHTML("beforeend", String(D.micon("check-circle-chip", 16)));
          });
          closeMenus();
          return this.refreshCards(page);
        }
        if (!e.target.closest(".d-menu")) closeMenus();

        const cmp = e.target.closest("[data-compare]");
        if (cmp) {
          const card = data().matches.cards.find((c) => c.compareId === cmp.dataset.compare);
          return D.toggleCompare(page, card.compareId, card.name);
        }
        const apply = e.target.closest("[data-apply]");
        if (apply) {
          e.stopPropagation();
          return D.apply(page, [apply.dataset.apply]);
        }
      });
      page.addEventListener("keydown", (e) => { if (e.key === "Escape") closeMenus(); });
    }
  };
})();

;

/* ==== js/desktop/screens/loan-offers.js ==== */
/* Desktop · Loans › Loan Offers — Figma 357:102436 (tags from 507:84666).
   Top 3 matches (the Overview cards) + All loan matches (horizontal cards) with chip
   filters, Sort (FLIP re-order), shared Compare selection. */
(function () {
  const { html } = OPL;
  const D = OPL.d;

  const allFor = (st) => {
    const lo = OPL.ddata.loanOffers;
    const cmp = D.compare.get();
    const list = lo.offers.filter((o) => st.chips.every((c) => D.CHIP_TEST[c](o.meta)));
    if (st.sorted) list.sort(D.SORTS[st.sort]);
    if (!list.length) {
      const e = OPL.ddata.loansOverview.matches.empty;
      return String(html`<div class="d-empty"><p class="d-empty__title">${e.title}</p><p class="d-empty__body">${e.body}</p>${D.btn({ label: e.cta, style: "outlined", size: "sm", attrs: "data-clear-chips" })}</div>`);
    }
    return list.map((o) => String(D.offerRow(o, { compared: cmp.includes(o.id) }))).join("");
  };

  OPL.dscreens["loan-offers"] = {
    title: "Loans · Loan Offers",
    figma: { frame: "357:102436" },
    st: { chips: [], sort: "Lowest interest", sorted: false },

    render(page) {
      const lo = OPL.ddata.loanOffers;
      const top = OPL.ddata.loansOverview.matches.cards;
      const cmp = D.compare.get();
      const st = this.st;
      page.innerHTML = D.shell({
        nav: "loans", title: "Loans", tab: "offers", counts: { compare: cmp.length || null },
        body: html`
          <div class="d-offers">
            <section class="d-offers__top" data-enter>
              <div class="d-sh"><h2 class="d-sh__title">${lo.topTitle}</h2></div>
              <div class="d-cards">${top.map((c) => D.offerCard(c, { compared: cmp.includes(c.compareId) }))}</div>
            </section>
            <section class="d-offers__all" data-enter>
              <div class="d-matches__head">
                <div class="d-sh"><h2 class="d-sh__title">${lo.allTitle}</h2></div>
                <div class="d-toolbar">
                  <div class="d-toolbar__chips">${lo.chips.map((c) => D.chipX(c, { selected: st.chips.includes(c.label) }))}</div>
                  ${D.sortFilter(st.sort)}
                </div>
              </div>
              <div class="d-rows-list" data-list>${OPL.raw(allFor(st))}</div>
            </section>
          </div>`,
      });
      D.mountShell(page);
      D.mountCompareBar(page);
      D.enter(page);
      D.bindListControls(page, st, () => D.flip(page.querySelector("[data-list]"), allFor(st), page));
      page.addEventListener("click", (e) => {
        const cmpBox = e.target.closest("[data-compare]");
        if (cmpBox) {
          const id = cmpBox.dataset.compare;
          const o = lo.offers.find((x) => x.id === id) || top.find((c) => c.compareId === id);
          return D.toggleCompare(page, id, o.name);
        }
        const apply = e.target.closest("[data-apply]");
        if (apply) { e.stopPropagation(); return D.apply(page, [apply.dataset.apply]); }
      });
    },
  };
})();

;

/* ==== js/desktop/screens/compare-loans.js ==== */
/* Desktop · Loans › Compare — Figma 507:85604 (empty, 0 of 3), 507:86537 (3 added),
   507:87387 (Selected + Apply bar), drawer 507:86111 (Add offers to compare).
   The added offers are the shared Compare selection (Overview / Loan Offers checkboxes,
   mobile Loan offers). Selected = lenders to apply to; the Apply bar rises with ≥1. */
(function () {
  const { html, raw } = OPL;
  const D = OPL.d;
  const C = () => OPL.ddata.compare;

  const resolve = (id) => {
    const c = C();
    if (c.records[id]) return id;
    const a = c.aliases[id];
    return a && c.records[a] ? a : null;
  };
  const addedIds = () => [...new Set(D.compare.get().map(resolve).filter(Boolean))].slice(0, 3);

  const valueCell = (row, rec, best) => {
    const v = rec.v[row.id];
    if (row.id === "collateral") return html`<div class="d-cmp__cell d-cmp__cell--inline">${v.map((x) => html`<span>${x}</span>`)}</div>`;
    const [main, sub] = Array.isArray(v) ? v : [v];
    return html`<div class="d-cmp__cell">
      <div class="d-cmp__val"><p>${main}</p>${sub ? html`<small>${sub}</small>` : ""}</div>
      ${best ? html`<span class="d-cmp__best">${best}</span>` : ""}
    </div>`;
  };

  const column = (id, sel, i) => {
    const c = C();
    const rec = c.records[id];
    const ids = addedIds();
    // best value per row among the added offers (only when they actually differ)
    const bestLabel = (rowId) => {
      const rule = c.best[rowId];
      if (!rule || ids.length < 2) return "";
      const vals = ids.map((x) => c.records[x].n[rowId]);
      if (vals.every((x) => x === vals[0])) return "";
      const win = rule[0] === "max" ? Math.max(...vals) : Math.min(...vals);
      return rec.n[rowId] === win ? rule[1] : "";
    };
    const on = sel.includes(id);
    return html`
      <div class="d-cmp__col ${on ? "is-selected" : ""}" data-col="${id}" style="--tint:${rec.tint};--i:${i}">
        <div class="d-cmp__head">
          <div class="d-cmp__id">
            ${D.logo(rec.logo)}
            <div class="d-cmp__name"><p class="d-card__name">${rec.name}</p><p class="d-card__sub">${rec.sub}</p></div>
            <button class="d-cmp__x" data-remove="${id}" aria-label="Remove ${rec.name}">${D.icon("close-circle-duo", 24)}</button>
          </div>
          <div class="d-cmp__amount"><p>Loan up to</p><b>${rec.v.amount}${bestLabel("amount") ? html`<span class="d-cmp__best">${bestLabel("amount")}</span>` : ""}</b></div>
        </div>
        ${c.rows.slice(2).map((row) => html`<div class="d-cmp__row" data-row="${row.id}">${valueCell(row, rec, bestLabel(row.id))}</div>`)}
        <div class="d-cmp__foot">
          ${on
            ? D.btn({ label: c.selected, style: "tonal", size: "md", cls: "d-btn--block", icon: D.icon("check-leading", 16), attrs: `data-select="${id}" aria-pressed="true"` })
            : D.btn({ label: c.select, style: "outlined", size: "md", cls: "d-btn--block", attrs: `data-select="${id}" aria-pressed="false"` })}
        </div>
      </div>`;
  };

  const emptySlot = (i) => {
    const e = C().empty;
    return html`
      <div class="d-cmp__slot" style="--i:${i}">
        <button class="d-cmp__add" data-browse aria-label="${e.title}">${D.icon("add-circle", 48)}</button>
        <div class="d-cmp__slot-copy"><p>${e.title}</p><small>${e.body}</small></div>
        <button class="d-cmp__browse" data-browse>${e.cta}${D.icon("caret-right-primary", 14)}</button>
      </div>`;
  };

  // Rows whose values are the same across every added offer (for "Show differences only")
  const sameRows = (ids) => {
    const c = C();
    if (ids.length < 2) return [];
    return c.rows.slice(1).filter((r) => {
      const vals = ids.map((id) => JSON.stringify(c.records[id].v[r.id]));
      return vals.every((v) => v === vals[0]);
    }).map((r) => r.id);
  };

  OPL.dscreens["compare-loans"] = {
    title: "Loans · Compare",
    figma: { frame: "507:87387" },
    sel: [],            // lenders picked to apply to
    diff: false,

    render(page) {
      const c = C();
      const ids = addedIds();
      this.sel = this.sel.filter((x) => ids.includes(x));
      const same = this.diff ? sameRows(ids) : [];
      page.innerHTML = D.shell({
        nav: "loans", title: "Loans", tab: "compare", counts: { compare: ids.length || null },
        body: html`
          <section class="d-cmp ${this.sel.length ? "has-bar" : ""}">
            <div class="d-cmp__bar">
              <div class="d-cmp__title"><h2>${c.title}</h2><span data-added>${c.added(ids.length)}</span></div>
              ${ids.length > 1 ? D.toggle({ on: this.diff, label: c.diffLabel, attrs: "data-diff" }) : ""}
            </div>
            <div class="d-cmp__grid ${this.diff ? "is-diff" : ""}">
              <div class="d-cmp__labels">
                ${c.rows.map((r) => html`<div class="d-cmp__label ${same.includes(r.id) ? "is-same" : ""}" data-row="${r.id}">${r.label}${r.info ? html`<span class="d-cmp__info" tabindex="0">${D.icon("info-glyph", 14)}${D.tip(r.info)}</span>` : ""}</div>`)}
              </div>
              ${[0, 1, 2].map((i) => (ids[i] ? column(ids[i], this.sel, i) : emptySlot(i)))}
            </div>
          </section>`,
        after: String(html`
          <div class="d-applybar ${this.sel.length ? "is-up" : ""}" data-applybar>
            ${D.btn({ label: c.apply, style: "filled", size: "lg", goto: "d-apply", attrs: "data-apply-selected" })}
          </div>`),
      });
      // the apply bar lives over the main panel (Figma: absolute, left 230, bottom 0)
      const bar = page.querySelector("[data-applybar]");
      page.querySelector(".d-main").appendChild(bar);
      page.querySelector(".d-main").classList.toggle("has-bar", this.sel.length > 0);
      if (same.length) same.forEach((r) => page.querySelectorAll(`.d-cmp__col [data-row="${r}"]`).forEach((el) => el.classList.add("is-same")));
      D.mountShell(page);
      D.enter(page);
      this.bind(page);
    },

    bind(page) {
      // row hover lights the label and every column's cell for that row
      const grid = page.querySelector(".d-cmp__grid");
      let hoverRow = null;
      const setRow = (r) => {
        if (r === hoverRow) return;
        if (hoverRow) grid.querySelectorAll(`[data-row="${hoverRow}"]`).forEach((el) => el.classList.remove("is-hover"));
        hoverRow = r;
        if (r && r !== "lender" && r !== "amount") grid.querySelectorAll(`[data-row="${r}"]`).forEach((el) => el.classList.add("is-hover"));
        if (r) grid.dataset.hoverRow = r; else delete grid.dataset.hoverRow;
      };
      grid?.addEventListener("pointerover", (e) => setRow(e.target.closest("[data-row]")?.dataset.row || null));
      grid?.addEventListener("pointerleave", () => setRow(null));
      page.addEventListener("click", (e) => {
        const rm = e.target.closest("[data-remove]");
        if (rm) {
          const id = rm.dataset.remove;
          const col = rm.closest(".d-cmp__col");
          const done = () => {
            D.compare.set(D.compare.get().filter((x) => resolve(x) !== id));
            this.sel = this.sel.filter((x) => x !== id);
            OPL.rerender();
          };
          if (D.motionOff()) return done();
          col.classList.add("is-leaving");
          return setTimeout(done, 240);
        }
        const pick = e.target.closest("[data-select]");
        if (pick) {
          const id = pick.dataset.select;
          this.sel = this.sel.includes(id) ? this.sel.filter((x) => x !== id) : [...this.sel, id];
          return this.updateSelection(page);
        }
        if (e.target.closest("[data-diff]")) {
          this.diff = !this.diff;
          const t = page.querySelector("[data-diff]");
          t.classList.toggle("is-on", this.diff);
          t.setAttribute("aria-checked", this.diff);
          const same = this.diff ? sameRows(addedIds()) : [];
          page.querySelector(".d-cmp__grid").classList.toggle("is-diff", this.diff);
          page.querySelectorAll(".d-cmp [data-row]").forEach((el) => el.classList.toggle("is-same", same.includes(el.dataset.row)));
          return;
        }
        if (e.target.closest("[data-browse]")) return this.openDrawer(page);
        const apply = e.target.closest("[data-apply-selected]");
        if (apply) { e.stopPropagation(); return D.apply(page, this.sel.slice()); }
      });
    },

    // Swap Select ↔ Selected in place and raise / lower the Apply bar
    updateSelection(page) {
      const c = C();
      page.querySelectorAll(".d-cmp__col").forEach((col) => {
        const id = col.dataset.col;
        const on = this.sel.includes(id);
        if (col.classList.contains("is-selected") === on) return;
        col.classList.toggle("is-selected", on);
        col.querySelector(".d-cmp__foot").innerHTML = String(on
          ? D.btn({ label: c.selected, style: "tonal", size: "md", cls: "d-btn--block is-popping", icon: D.icon("check-leading", 16), attrs: `data-select="${id}" aria-pressed="true"` })
          : D.btn({ label: c.select, style: "outlined", size: "md", cls: "d-btn--block", attrs: `data-select="${id}" aria-pressed="false"` }));
      });
      const up = this.sel.length > 0;
      page.querySelector("[data-applybar]").classList.toggle("is-up", up);
      page.querySelector(".d-main").classList.toggle("has-bar", up);
    },

    openDrawer(page) {
      const c = C();
      const lo = OPL.ddata.loanOffers;
      const byId = Object.fromEntries(lo.offers.map((o) => [o.id, o]));
      let picked = addedIds();
      const st = { chips: [], q: "" };
      const list = () => c.drawer.order
        .map((id) => byId[id])
        .filter((o) => st.chips.every((ch) => D.CHIP_TEST[ch](o.meta)))
        .filter((o) => !st.q || (o.name + " " + o.sub).toLowerCase().includes(st.q))
        .map((o) => String(D.offerRow(o, { selectable: true, selected: picked.includes(o.id) }))).join("")
        || `<p class="d-drawer__none">No offers match “${st.q}”</p>`;
      const body = String(html`
        <label class="d-dsearch">${D.icon("drawer-search", 16)}<input type="search" placeholder="${c.drawer.search}" aria-label="${c.drawer.search}" data-dsearch></label>
        <div class="d-toolbar__chips d-drawer__chips">${c.drawer.chips.map((ch) => html`<button class="d-chip" aria-pressed="false" data-dchip="${ch}">${ch}</button>`)}</div>
        <div class="d-drawer__list" data-dlist>${raw(list())}</div>`);
      const footer = String(html`<span class="d-drawer__count" data-dcount>${picked.length} of 3 selected</span>${D.btn({ label: c.drawer.cta, style: "filled", size: "md", cls: "d-drawer__cta", attrs: "data-dselect" })}`);
      const dr = D.openDrawer(page, { title: c.drawer.title, body, footer });
      const listEl = dr.el.querySelector("[data-dlist]");
      const refresh = () => { listEl.innerHTML = list(); };
      dr.el.querySelector("[data-dsearch]").addEventListener("input", (e) => { st.q = e.target.value.trim().toLowerCase(); refresh(); });
      dr.el.addEventListener("click", (e) => {
        const chip = e.target.closest("[data-dchip]");
        if (chip) {
          const ch = chip.dataset.dchip;
          st.chips = st.chips.includes(ch) ? st.chips.filter((x) => x !== ch) : [...st.chips, ch];
          chip.classList.toggle("is-selected"); chip.setAttribute("aria-pressed", st.chips.includes(ch));
          return refresh();
        }
        const row = e.target.closest(".d-row-card--pick");
        if (row) {
          const id = row.dataset.offer;
          if (picked.includes(id)) picked = picked.filter((x) => x !== id);
          else if (picked.length < 3) picked = [...picked, id];
          else {
            row.animate([{ transform: "translateX(0)" }, { transform: "translateX(-4px)" }, { transform: "translateX(4px)" }, { transform: "none" }], { duration: 240 });
            dr.el.querySelector("[data-dcount]").classList.add("is-max");
            return;
          }
          const on = picked.includes(id);
          row.classList.toggle("is-picked", on);
          row.setAttribute("aria-checked", on);
          const count = dr.el.querySelector("[data-dcount]");
          count.textContent = `${picked.length} of 3 selected`;
          count.classList.remove("is-max");
          return;
        }
        if (e.target.closest("[data-dselect]")) {
          D.compare.set(picked.slice());
          dr.close();
          setTimeout(() => OPL.rerender(), 120);
        }
      });
      dr.el.addEventListener("keydown", (e) => {
        if ((e.key === "Enter" || e.key === " ") && e.target.classList.contains("d-row-card--pick")) { e.preventDefault(); e.target.click(); }
      });
    },
  };
})();

;

/* ==== js/desktop/screens/applications.js ==== */
/* Desktop · Loans › Applications — Figma 440:134641 (list) + 440:137299 ("Citi Bank
   approved your loan" modal over the list). State is the mobile kit's (OPL.apps), so an
   application submitted or advanced in either view shows the same status here.
   Live demo (as on mobile): a few seconds after submitting, the first lender approves and
   the milestone modal plays its confetti. */
(function () {
  const { html, raw } = OPL;
  const D = OPL.d;
  const A = () => OPL.data.applications;

  const COPY = {                         // verbatim 440:134641
    title: "Your Applications",
    note: "You can accept one KFS this month. When you accept one, your other applications close.",
    verifying: [
      { state: "done", label: "Application Sent", sub: "22 Nov, 11:40 am" },
      { state: "progress", label: "Lender Verification", sub: "In progress · Takes ~5 to 7 working days" },
      { state: "todo", label: "Sign KFS and Sanction", sub: "Final offer, KFS and sanction letter" },
    ],
    kfs: [
      { state: "done", label: "Application Sent", sub: "22 Nov, 11:40 am" },
      { state: "done", label: "Lender Verification", sub: "Verified on 24 Nov" },
      { state: "action", label: "Sign KFS and Sanction", sub: "Sign by 25 Nov" },
    ],
    kfsFigures: [
      { label: "Final offer", value: "₹45 L" },
      { label: "Interest", value: "9.45%", unit: "p.a." },
      { label: "APR", value: "10.54%" },
      { label: "Monthly EMI", value: "₹1,44,043", unit: "/ month" },
    ],
  };
  const LATE = ["kfs", "sign", "signed", "disbursing", "disbursed"];

  const logoFor = (id) => {
    const r = OPL.ddata.compare.records[OPL.ddata.compare.aliases[id] || id];
    return r ? r.logo : OPL.img("logo-sbi.png");
  };

  const card = (a) => {
    const l = OPL.apps.lender(a.id);
    const late = LATE.includes(a.status);
    const figs = late ? COPY.kfsFigures : [{ label: "Loan offer", value: l.amountShort }, { label: "Interest", value: "9.45%", unit: "p.a." }];
    return html`
      <article class="d-appcard" data-app="${a.id}" style="--tint:${l.tint}" tabindex="0">
        <div class="d-appcard__head">
          <div class="d-appcard__id">${D.logo(logoFor(a.id))}<div><p class="d-card__name">${l.name}</p><p class="d-card__sub">${l.type}</p></div></div>
          ${late ? html`<span class="d-appcard__tag">${D.icon("clock-amber", 16)}${A().kfs.daysLeft}</span>` : ""}
        </div>
        <div class="d-appcard__body">
          <div class="d-appcard__row">
            <div class="d-appcard__figs">${figs.map((f) => html`<div class="d-fig"><p class="d-fig__label">${f.label}</p><p class="d-fig__value">${f.value}${f.unit ? html`<small>${f.unit}</small>` : ""}</p></div>`)}</div>
            ${late
              ? D.btn({ label: "Review KFS", style: "filled", size: "lg", iconRight: D.icon("btn-arrow-white", 16), attrs: `data-app-open="${a.id}"` })
              : D.btn({ label: "View details", style: "outlined", size: "lg", cls: "d-btn--neutral", iconRight: D.micon("chevron-right-primary", 16), attrs: `data-app-open="${a.id}"` })}
          </div>
          ${D.hSteps(late ? COPY.kfs : COPY.verifying)}
        </div>
      </article>`;
  };

  OPL.dscreens.applications = {
    title: "Loans · Applications",
    figma: { list: "440:134641", approved: "440:137299" },
    timers: [],
    leave() { this.timers.forEach(clearTimeout); this.timers = []; },

    render(page) {
      this.leave();
      const apps = OPL.apps.currentApps();
      const m = OPL.screens.applications;          // mobile list state (live apps + "fresh" flag)
      page.innerHTML = D.shell({
        nav: "loans", title: "Loans", tab: "applications", counts: { compare: D.compare.get().length || null },
        body: html`
          <section class="d-apps">
            <div class="d-apps__head">
              <h2 class="d-sh__title">${COPY.title}${D.count(apps.length)}</h2>
              ${D.whatsappPill(true)}
            </div>
            <div class="d-apps__list">${apps.map(card)}</div>
            ${D.noteRow(COPY.note)}
          </section>`,
      });
      D.mountShell(page);
      if (!D.motionOff()) {
        page.querySelectorAll(".d-appcard, .d-note").forEach((el, i) => { el.classList.add("d-enter"); el.style.setProperty("--d", `${i * 80}ms`); });
        OPL.afterReveal(() => setTimeout(() => page.querySelectorAll(".d-enter").forEach((el) => el.classList.add("is-in")), 16));
        // steps fill in once their card has arrived
        OPL.afterReveal(() => this.timers.push(setTimeout(() => page.querySelectorAll(".d-steps").forEach((s) => s.classList.add("is-in")), 260)));
      } else page.querySelectorAll(".d-steps").forEach((s) => s.classList.add("is-in"));

      page.addEventListener("click", (e) => {
        const o = e.target.closest("[data-app-open]") || (!e.target.closest("button") && e.target.closest("[data-app]"));
        if (o) return OPL.go("application", { app: o.dataset.appOpen || o.dataset.app });
        const wa = e.target.closest("[data-wa]");
        if (wa) { wa.classList.toggle("is-on"); wa.setAttribute("aria-checked", wa.classList.contains("is-on")); }
      });
      page.addEventListener("keydown", (e) => { if (e.key === "Enter" && e.target.matches("[data-app]")) OPL.go("application", { app: e.target.dataset.app }); });

      // Figma preset (#ms=on) or the live demo: the approval milestone
      const v = OPL.state.get();
      if (v.ms === "on") OPL.afterReveal(() => this.openApproved(page, "pick-citi"));
      if (m && m.fresh && m.apps && m.apps.length) {
        m.fresh = false;
        OPL.afterReveal(() => this.timers.push(setTimeout(() => {
          if (!page.isConnected) return;
          const first = m.apps[0];
          first.status = "kfs";
          const fresh = OPL.rerender();
          this.timers.push(setTimeout(() => fresh.isConnected && this.openApproved(fresh, first.id), D.motionOff() ? 0 : 500));
        }, D.motionOff() ? 300 : (A().demo && A().demo.toApproved) || 3500)));
      }
    },

    // 440:137299 — the mobile milestone (confetti, ripple, logo + tick) in a 480 modal
    openApproved(page, id) {
      const d = A(), l = OPL.apps.lender(id);
      const body = OPL.ui.MilestoneApproved({
        lender: l.name, logo: l.logo, type: l.type, title: d.kfs.approvedTitle(l.name), body: d.kfs.approvedBody, note: d.kfs.approvedNote,
        figures: [{ label: "Final offer", value: d.kfs.finalOffer }, { label: "Interest", value: "9.45%", unit: "p.a." }, { label: "APR", value: id === "pick-citi" ? d.kfs.summary.apr : l.apr }],
      }).toString();
      const m = D.openModal(page, `<div class="d-ms">${body}</div>`, { width: 480, cls: "sheet-layer d-modal--ms" });
      m.el.addEventListener("click", (e) => {
        if (e.target.closest("[data-ms-review]")) { m.close(); this.timers.push(setTimeout(() => OPL.go("application", { app: id }), 240)); }
      });
    },
  };
})();

;

/* ==== js/desktop/screens/application.js ==== */
/* Desktop · Application page — Figma section "final-loan applications" 440:134259:
   verifying 440:136328 · KFS ready 440:136512 · money on its way 440:136901 ·
   money in account 440:137099 · sanction signed 440:136706.
   Layout as drawn: breadcrumbs → main column (summary card, status story card with the
   timeline, repayment card) + 340 rail (Branch details, Documents / documents to keep
   ready, WhatsApp, Withdraw). The timeline, info cards and milestone sheets are the mobile
   kit's, so status, copy and delight match mobile one-to-one. Status = OPL.apps (shared). */
(function () {
  const { html, raw, ui } = OPL;
  const D = OPL.d;
  const A = () => OPL.data.applications;

  const COPY = {                                   // desktop-only copy, verbatim from the frames
    appId: "LA-2026-10-6101",
    beforeTitle: "Before you sign",
    before: [
      { text: "Accept the KFS and sign the sanction letter by 25 Nov 2026.", tone: "warning" },
      { text: "You can accept one KFS this month. Other ongoing loan applications close once you accept this.", tone: "info" },
    ],
    expectTitle: "What to expect",
    expectVerifying: (name) => [`${name} will call you on +91 ******6789.`, "They may visit your unit on Ring Road, Surat."],
    expectMoney: (name) => ["Expected in your account by 30 Nov.", `${name} may call you to confirm details before disbursal of the final loan amount.`],
    repayTitle: "Total Repayment Amount",
    docsReady: "Keep these documents ready",
    withdraw: "Withdraw application",
  };
  const logoFor = (id) => {
    const c = OPL.ddata.compare;
    const r = c.records[c.aliases[id] || id];
    return r ? r.logo : OPL.img("logo-sbi.png");
  };

  const timelineFor = (st, l, d) => {
    const money = st === "disbursing" || st === "disbursed";
    if (money) return [
      { icon: "plain-2", state: "done", title: `Sent to ${l.name}`, sub: d.sentAt },
      { icon: "buildings", state: "done", title: "Lender Verification", sub: d.verifiedOn, pad: 0 },
      { icon: "document-text-done", state: "done", title: d.signed.step3, sub: d.signed.step3Sub, pad: 0, line: st === "disbursing" ? "fade-blue" : "" },
      st === "disbursing"
        ? { icon: "wallet-money", state: "progress", title: d.disbursing.step4, sub: d.disbursing.step4Sub(l.name), pad: 6 }
        : { icon: "wallet-money", state: "done", strong: true, title: d.disbursed.step4, sub: d.disbursed.step4Sub, pad: 6 },
    ];
    if (st === "sign" || st === "signed") return [
      { icon: "plain-2", state: "done", title: `Sent to ${l.name}`, sub: d.sentAt },
      { icon: "buildings", state: "done", title: "Lender Verification", sub: d.verifiedOn, line: st === "sign" ? "fade" : "", pad: 0 },
      st === "signed"
        ? { icon: "document-text-done", state: "done", strong: true, title: d.signed.step3, sub: d.signed.step3Sub, pad: 6 }
        : { icon: "document-text", state: "action", title: d.sign.step3, sub: d.sign.step3Sub, pad: 6 },
    ];
    if (st === "kfs") return [
      { icon: "plain-2", state: "done", title: `Sent to ${l.name}`, sub: d.sentAt },
      { icon: "buildings", state: "done", title: "Lender Verification", sub: d.verifiedOn, pad: 0 },
      { icon: "document-text", state: "action", title: d.kfs.title, pad: 6 },
    ];
    return [
      { icon: "plain-2", state: "done", title: `Sent to ${l.name}`, sub: d.sentAt },
      { icon: "buildings-primary", state: "current", title: "Lender Verification", sub: d.verifying.progress, subTone: "primary" },
      { icon: "document-text-muted", state: "todo", title: d.verifying.todo },
    ];
  };

  const repayCard = (s) => html`
    <section class="d-panel d-repay" data-enter>
      <div class="d-repay__head"><p>${COPY.repayTitle}</p><b>${s.repay}</b></div>
      <div class="kfs-repay__bar d-repay__bar">${s.split.map((p) => raw(`<span style="flex:${p.w} 0 0;background:${p.color}"></span>`))}</div>
      <div class="kfs-repay__legend">${s.split.map((p) => raw(`<div>${OPL.icon(p.dot, 8)}<span>${p.label}</span><b>${p.value}</b></div>`))}</div>
    </section>`;

  OPL.dscreens.application = {
    title: "Loans · Application",
    figma: { verifying: "440:136328", kfs: "440:136512", disbursing: "440:136901", disbursed: "440:137099", signed: "440:136706" },
    timers: [],
    leave() { this.timers.forEach(clearTimeout); this.timers = []; },

    render(page) {
      this.leave();
      const d = A();
      const apps = OPL.apps.currentApps();
      const q = OPL.state.get();
      const id = q.app || apps[0].id;
      const st = q.st || OPL.apps.statusOf(id);
      const l = OPL.apps.lender(id);
      const verifying = !["kfs", "sign", "signed", "disbursing", "disbursed"].includes(st);
      const money = st === "disbursing" || st === "disbursed";
      const s = d.kfs.summary;

      const figures = verifying
        ? [{ label: "Loan offer", value: l.amountShort }, { label: "Interest rate", value: "9.45%", unit: "p.a. floating" }, { label: "Loan type", value: "Term loan" }, { label: "Decision expected", value: "5–7 working days" }]
        : [{ label: "Final offer", value: d.kfs.finalOffer }, { label: "Interest rate", value: "9.45%", unit: "p.a. floating" }, { label: "APR", value: s.apr }, { label: "Monthly EMI", value: s.emi }];

      const title = { kfs: d.kfs.title, sign: d.sign.title, signed: d.signed.title, disbursing: d.disbursing.title, disbursed: d.disbursed.title }[st] || d.verifying.title(l.name);
      const cta = st === "kfs" ? D.btn({ label: "Review KFS & Accept", style: "filled", size: "lg", iconRight: D.icon("btn-arrow-white", 16), attrs: "data-review-kfs" })
        : st === "sign" ? D.btn({ label: d.sign.cta, style: "filled", size: "lg", iconRight: OPL.icon("arrow-square-out-white", 16), attrs: "data-sign-nesl" }) : "";
      const notes = st === "kfs" || st === "sign"
        ? html`<div class="d-story__sub"><p class="d-story__h">${COPY.beforeTitle}</p>${COPY.before.map((n) => ui.NoteRow(n))}</div>`
        : verifying || money
        ? html`<div class="d-story__sub"><p class="d-story__h">${COPY.expectTitle}</p>${(verifying ? COPY.expectVerifying(l.name) : COPY.expectMoney(l.name)).map((t) => ui.NoteRow({ text: t, tone: "info" }))}</div>`
        : "";
      const branch = ui.InfoCard({ title: "Branch Details", body: ui.ContactList(d.branch(l.slug)) });
      const docs = ui.InfoCard({ title: "Documents", body: ui.LinkList({ items: d.docs }) });
      const ready = ui.InfoCard({ title: COPY.docsReady, body: ui.DocList({ items: d.verifying.docs }) });

      page.innerHTML = D.shell({
        nav: "loans", title: "", tab: null,
        crumbs: [{ label: "Loans", goto: "loans-overview" }, { label: "Applications", goto: "applications" }, { label: `Loan details - ${l.name}` }],
        body: html`
          <div class="d-appd" style="--tint:${l.tint}">
            <div class="d-appd__main">
              <section class="d-appd__summary" data-enter>
                <div class="d-appd__head">
                  <span class="d-appd__id-tag">Application ID: <b>${COPY.appId}</b></span>
                  <div class="d-appd__who">${D.logo(logoFor(id))}<div><h1>${l.name}</h1><p>${l.type}</p></div></div>
                </div>
                <div class="d-appd__figs">${figures.map((f) => html`<div class="d-appd__fig"><p>${f.label}</p><b>${f.value}${f.unit ? html`<small>${f.unit}</small>` : ""}</b></div>`)}</div>
              </section>
              <section class="d-panel d-story" data-enter>
                <div class="d-story__top"><h2>${title}</h2>${cta}</div>
                ${st === "disbursing" ? html`<p class="d-story__eta">${d.disbursing.sub}</p>` : ""}
                ${ui.Timeline({ items: timelineFor(st, l, d) })}
                ${notes}
              </section>
              ${verifying ? "" : repayCard(s)}
            </div>
            <aside class="d-appd__rail" data-enter>
              ${branch}
              ${verifying ? ready : money || st === "signed" ? docs : ""}
              ${ui.WhatsAppRow({ label: d.whatsapp })}
              ${money && st === "disbursed" ? "" : html`<button class="d-withdraw" data-goto="withdraw">${COPY.withdraw}</button>`}
            </aside>
          </div>`,
      });
      page.querySelectorAll(".d-appd__rail .info-card").forEach((c) => c.classList.add("is-open"));
      D.mountShell(page);
      D.enter(page);
      OPL.fx.playInView(page, ".tl, .d-repay");
      this.bind(page, { id, l, st });

      // Milestones (as on mobile): arriving from NeSL → Signed; the live demo then moves to
      // Money on its way → Money received with the Disbursed moment.
      const m = OPL.screens.application;           // shared flags (mobile NeSL sets .celebrate)
      if (st === "signed" && (m.celebrate || q.ms === "on")) {
        const live = m.celebrate; m.celebrate = false;
        OPL.afterReveal(() => this.timers.push(setTimeout(() => page.isConnected && this.openSigned(page, l, id, live), live && !D.motionOff() ? 460 : 0)));
      }
      if (st === "disbursing" && m.progressNext) {
        m.progressNext = false;
        this.timers.push(setTimeout(() => {
          if (!page.isConnected) return;
          OPL.apps.setStatus(id, "disbursed"); m.celebrateMoney = true; OPL.rerender();
        }, D.motionOff() ? 300 : d.demo.toDisbursed));
      }
      if (st === "disbursed" && (m.celebrateMoney || q.ms === "on")) {
        const live = m.celebrateMoney; m.celebrateMoney = false;
        OPL.afterReveal(() => this.timers.push(setTimeout(() => page.isConnected && this.openDisbursed(page), live && !D.motionOff() ? 700 : 0)));
      }
    },

    bind(page, { id }) {
      page.addEventListener("click", (e) => {
        const acc = e.target.closest("[data-accordion]");
        if (acc) return acc.closest(".info-card").classList.toggle("is-open");
        const cp = e.target.closest("[data-copy]");
        if (cp) {
          navigator.clipboard?.writeText(cp.dataset.copy).catch(() => {});
          cp.classList.remove("is-copied"); void cp.offsetWidth; cp.classList.add("is-copied");
          return D.toast(page, "Copied");
        }
        const wa = e.target.closest("[data-wa]");
        if (wa) { wa.classList.toggle("is-on"); wa.setAttribute("aria-checked", wa.classList.contains("is-on")); return; }
        if (e.target.closest("[data-review-kfs]")) return OPL.go("kfs", { app: id });
        if (e.target.closest("[data-sign-nesl]")) return OPL.go("nesl", { app: id, step: null });
      });
    },

    // 440:136706 — "Sanction letter signed" (mobile MilestoneSigned) in a 480 modal
    openSigned(page, l, id, live) {
      const d = A().signed.sheet;
      let advanced = false;
      const body = ui.MilestoneSigned({ ...d, body: d.body(l.name) }).toString();
      const m = D.openModal(page, `<div class="d-ms">${body}</div>`, { width: 480, cls: "sheet-layer d-modal--ms", onClose: () => {
        if (!live || advanced) return; advanced = true;
        this.timers.push(setTimeout(() => {
          if (!page.isConnected) return;
          OPL.apps.setStatus(id, "disbursing"); OPL.screens.application.progressNext = true; OPL.rerender();
        }, D.motionOff() ? 300 : A().demo.toDisbursing));
      } });
      m.el.addEventListener("click", (e) => { if (e.target.closest("[data-ms-view], [data-ms-done]")) m.close(); });
    },

    // 440:137099 — "Money disbursed" (mobile MilestoneDisbursed): full burst, amount counts up
    openDisbursed(page) {
      const d = A().disbursed.sheet;
      const m = D.openModal(page, `<div class="d-ms">${ui.MilestoneDisbursed(d)}</div>`, { width: 480, cls: "sheet-layer d-modal--ms" });
      m.el.addEventListener("click", (e) => {
        if (e.target.closest("[data-ms-done]")) m.close();
        if (e.target.closest("[data-ms-view]")) { m.close(); this.timers.push(setTimeout(() => OPL.go("my-loans"), 240)); }
      });
      const el = m.el.querySelector("[data-ms-amount]");
      const to = Number(d.amount.replace(/[^\d]/g, ""));
      if (el && !D.motionOff()) {
        const t0 = Date.now() + 260, dur = 1100;
        const tick = () => {
          const k = Math.max(0, Math.min(1, (Date.now() - t0) / dur)), e = 1 - Math.pow(1 - k, 3);
          el.textContent = "₹" + Math.round(to * e).toLocaleString("en-IN");
          if (k < 1 && el.isConnected) this.timers.push(setTimeout(tick, 16));
        };
        el.textContent = "₹0"; tick();
      }
    },
  };
})();

;

/* ==== js/desktop/screens/kfs.js ==== */
/* Desktop · KFS reader — Figma 440:134934 (two-pane, unread) → read + consent → Accept KFS.
   Approved desktop decision: the KFS summary and the PDF are one screen (one step fewer
   than mobile). Left: the document (same pages as mobile, OPL.data.kfsDoc) with a file
   bar, read-progress line and a floating page counter. Right (380): APR card, You repay,
   fact chips and the consent card. Reading to the last page unlocks consent → Accept KFS
   → "Sign on NeSL" (the mobile Step 2 sheet, 433:7980) in a modal. */
(function () {
  const { html, raw, ui } = OPL;
  const D = OPL.d;
  const K = () => OPL.data.kfsDoc;

  const row = ([n, label, value], i) =>
    `<div class="kfs-row${i % 2 ? " kfs-row--alt" : ""}"><span class="kfs-row__n">${n}</span><span class="kfs-row__l">${label}</span><span class="kfs-row__v">${value}</span></div>`;
  const ack = (a) => `<div class="kfs-ack"><p class="kfs-ack__title">${a.title}</p><p class="kfs-ack__text">${a.text}</p>
    <div class="kfs-ack__sign">${a.lines.map((t) => `<div><span></span><p>${t}</p></div>`).join("")}</div><p class="kfs-ack__foot">${a.foot}</p></div>`;
  const pageEl = (p, i, total, head) => `
    <article class="kfs-page d-kfs__page" data-kfs-page="${i}">
      <div class="kfs-page__lh">${ui.Logo({ id: head.logo, size: 16 })}<span class="kfs-page__org">${head.name}</span><span class="kfs-page__no">Page ${i + 1} of ${total}</span></div>
      <span class="kfs-page__rule"></span>
      ${p.title ? `<h3 class="kfs-page__title">${p.title}</h3>` : ""}
      ${p.meta ? `<p class="kfs-page__meta">${p.meta}</p>` : ""}
      <h4 class="kfs-page__part">${p.part}</h4>
      <div class="kfs-table">${p.rows.map(row).join("")}</div>
      ${p.note ? `<p class="kfs-page__note">${p.note}</p>` : ""}
      ${p.ack ? ack(p.ack) : ""}
    </article>`;

  OPL.dscreens.kfs = {
    title: "Loans · Key Fact Statement",
    figma: { reader: "440:134934" },
    timers: [],
    leave() { this.timers.forEach(clearTimeout); this.timers = []; },

    render(page, { read = false } = {}) {
      this.leave();
      const d = K();
      const a = OPL.data.applications;
      const apps = OPL.apps.currentApps();
      const id = OPL.state.get().app || (apps.find((x) => x.status === "kfs") || {}).id || "pick-citi";
      const l = OPL.apps.lender(id);
      const head = { logo: l.logo, name: d.letterhead[id] || l.name };
      const pages = d.pages(l);
      const s = a.kfs.summary;

      page.innerHTML = D.shell({
        nav: "loans", title: "", tab: null,
        crumbs: [{ label: "Loans", goto: "loans-overview" }, { label: "Applications", goto: "applications" }, { label: `Loan detail - ${l.name}`, goto: "application" }, { label: "Sign KFS and Sanction Letter" }],
        body: html`
          <div class="d-kfs">
            <div class="d-kfs__bar">
              <h1 class="d-kfs__title"><button class="d-kfs__back" data-back aria-label="Back">${OPL.icon("arrow-left", 24)}</button>${l.name} Key Fact Statement</h1>
              ${D.btn({ label: "Download PDF", style: "outlined", size: "sm", cls: "d-btn--neutral", iconRight: OPL.icon("download", 16), goto: "kfs-download" })}
            </div>
            <div class="d-kfs__steps">
              <span class="d-kfs__step is-on"><i>${OPL.icon("document-text", 16)}</i>Step 1 · Accept KFS</span>
              <span class="d-kfs__step"><i>${OPL.icon("document-text-muted", 16)}</i>Step 2 · Sign sanction letter on NeSL</span>
            </div>
            <div class="d-kfs__grid">
              <section class="d-kfs__doc">
                <div class="d-kfs__file"><span>${l.name.split(" ")[0]}_Bank_KFS_LA-2026-11-2231.pdf</span><span><b data-kfs-n>1</b> of ${pages.length} · 100%</span></div>
                <span class="d-kfs__read"><i data-kfs-bar style="width:${100 / pages.length}%"></i></span>
                <div class="d-kfs__scroll" data-kfs-scroll>${raw(pages.map((p, i) => pageEl(p, i, pages.length, head)).join(""))}<p class="kfs-end">${d.end}</p></div>
                <span class="d-kfs__counter"><b data-kfs-n2>1</b> / ${pages.length}</span>
              </section>
              <aside class="d-kfs__rail">
                ${ui.AprCard({ s, bordered: true })}
                <div class="d-panel d-kfs__repay">
                  <div class="d-repay__head"><p>You repay</p><b>${s.repay}</b></div>
                  <div class="kfs-repay__bar d-repay__bar">${s.split.map((p) => raw(`<span style="flex:${p.w} 0 0;background:${p.color}"></span>`))}</div>
                  <div class="kfs-repay__legend">${s.split.map((p) => raw(`<div>${OPL.icon(p.dot, 8)}<span>${p.label}</span><b>${p.value}</b></div>`))}</div>
                </div>
                <div class="kfs-facts d-kfs__facts">${s.facts.map((f) => raw(`<span>${f}</span>`))}</div>
                <div class="d-panel d-kfs__consent">
                  <button class="d-kfs__check" data-kfs-consent aria-pressed="false" disabled>${OPL.icon("check-square", 24)}<span>I have read and understood the Key Fact Statement</span></button>
                  ${D.btn({ label: d.cta, style: "filled", size: "lg", cls: "d-btn--block", attrs: "disabled data-kfs-accept" })}
                  <p class="d-kfs__hint" data-kfs-hint>${d.hint}</p>
                </div>
              </aside>
            </div>
          </div>`,
      });
      D.mountShell(page);
      this.bind(page, id, pages.length);
      if (read || OPL.state.get().read === "on") this.markRead(page);
    },

    // 476:230861 — "Sign your sanction letter on NeSL" (Step 2 of 2), over the read KFS
    openSignModal(page, id) {
      OPL.apps.setStatus(id, "sign");
      const steps = ["Verify OTP", "Read the Sanction Letter", "Confirm e-stamp", "eSign with Aadhaar"];
      const body = String(html`
        <div class="d-signm">
          <div class="d-signm__head">
            <div class="d-signm__progress"><span class="d-signm__ok">${D.icon("check-circle-green", 14)}KFS accepted</span><span>Step 2 of 2</span></div>
            <h2>Sign your sanction letter on NeSL</h2>
          </div>
          <ol class="d-signm__steps">${steps.map((t, i) => html`<li style="--i:${i}"><span class="d-signm__rail"><b>${i + 1}</b>${i < steps.length - 1 ? html`<i></i>` : ""}</span><span class="d-signm__t">${t}</span></li>`)}</ol>
          ${ui.NoteRow({ text: "Sign sanction letter before 25 Nov 2026", tone: "warning" })}
          <div class="d-signm__actions">
            ${D.btn({ label: "Continue to NeSL", style: "filled", size: "lg", cls: "d-btn--block d-signm__go", iconRight: D.icon("external-white", 16), attrs: "data-nesl-go" })}
            <button class="d-signm__later" data-nesl-later>I’ll come back later</button>
          </div>
        </div>`);
      const m = D.openModal(page, body, { width: 520, cls: "d-modal--sign" });
      m.el.addEventListener("click", (e) => {
        if (e.target.closest("[data-nesl-go]")) { m.close(); this.timers.push(setTimeout(() => OPL.go("nesl", { app: id, step: null }), 200)); }
        if (e.target.closest("[data-nesl-later]")) { m.close(); this.timers.push(setTimeout(() => OPL.go("application", { app: id }, { replace: true }), 200)); }
      });
    },

    // KFS read to the end with consent ticked (476:230649 backdrop)
    markRead(page) {
      const sc = page.querySelector("[data-kfs-scroll]");
      sc.scrollTop = sc.scrollHeight;
      sc.dispatchEvent(new Event("scroll"));
      const c = page.querySelector("[data-kfs-consent]");
      c.disabled = false; c.setAttribute("aria-pressed", "true");
      c.querySelector("img").src = "assets/icons/check-square-checked.svg";
      page.querySelector("[data-kfs-accept]").disabled = false;
      page.querySelector("[data-kfs-hint]").classList.add("is-done");
    },

    bind(page, id, total) {
      const sc = page.querySelector("[data-kfs-scroll]");
      const n = page.querySelector("[data-kfs-n]"), n2 = page.querySelector("[data-kfs-n2]");
      const bar = page.querySelector("[data-kfs-bar]");
      const consent = page.querySelector("[data-kfs-consent]");
      const accept = page.querySelector("[data-kfs-accept]");
      const hint = page.querySelector("[data-kfs-hint]");
      const pagesEls = [...sc.querySelectorAll("[data-kfs-page]")];
      let unlocked = false;
      const onScroll = () => {
        const max = sc.scrollHeight - sc.clientHeight;
        const k = max > 0 ? sc.scrollTop / max : 1;
        bar.style.width = `${Math.max(100 / total, k * 100)}%`;
        const mid = sc.scrollTop + sc.clientHeight * 0.4;
        let cur = 0;
        pagesEls.forEach((p, i) => { if (p.offsetTop <= mid) cur = i; });
        n.textContent = n2.textContent = cur + 1;
        if (!unlocked && k > 0.97) {
          unlocked = true;
          consent.disabled = false;
          consent.classList.add("is-ready");
          hint.classList.add("is-done");
        }
      };
      sc.addEventListener("scroll", onScroll, { passive: true });
      consent.addEventListener("click", () => {
        const on = consent.getAttribute("aria-pressed") !== "true";
        consent.setAttribute("aria-pressed", on);
        consent.querySelector("img").src = `assets/icons/${on ? "check-square-checked" : "check-square"}.svg`;
        consent.classList.remove("is-popping"); void consent.offsetWidth; consent.classList.add("is-popping");
        accept.disabled = !on;
      });
      // the hint itself scrolls to the end (a desktop shortcut for presenting)
      hint.addEventListener("click", () => sc.scrollTo({ top: sc.scrollHeight, behavior: D.motionOff() ? "auto" : "smooth" }));
      accept.addEventListener("click", () => this.openSignModal(page, id));
    },
  };
})();

;

/* ==== js/desktop/screens/nesl.js ==== */
/* Desktop · NeSL signing — Figma section "nesl" 524:105163.
   Over the KFS (read, consent ticked) and a dark overlay, NeSL's own desktop portal opens
   as drawn: Agreement Preview (476:231547, scroll to read) → Agreement Preview, end, I AGREE
   (476:231121) → E-Stamp Details, Next (476:231334) → NSDL eSign OTP, Verify OTP (476:231761)
   → "Confirming your signature" (476:231762) → application Signed + milestone (476:232230).
   Each screen is the third-party screenshot with a hotspot on its real button; clicking
   elsewhere flashes it (Figma-prototype convention). CANCEL → application, left before signing.
   Order: Figma lays the frames out m2 · m3 · 231547 · m4; the reading order used here puts the
   unscrolled agreement first (flagged in the README). */
(function () {
  const { html } = OPL;
  const D = OPL.d;
  // display size in the 1440 frame; hotspots in those display px [x, y, w, h]
  const STEPS = [
    { id: "agreement-top", figma: "476:231547", w: 1055, h: 517, scrollToNext: true, next: [170, 89, 715, 340], cancel: [460, 468, 145, 24] },
    { id: "agreement-end", figma: "476:231121", w: 1055, h: 517, next: [374, 478, 147, 25], cancel: [531, 478, 144, 25] },
    { id: "estamp", figma: "476:231334", w: 1055, h: 497, next: [457, 297, 141, 23] },
    { id: "esign-otp", figma: "476:231761", w: 943, h: 517, next: [488, 330, 62, 26], cancel: [553, 330, 45, 26] },
  ];
  const src = (id) => `assets/lazy/dsk/nesl/${id}.jpg`;
  const box = (s, r) => `left:${(r[0] / s.w) * 100}%;top:${(r[1] / s.h) * 100}%;width:${(r[2] / s.w) * 100}%;height:${(r[3] / s.h) * 100}%`;

  OPL.dscreens.nesl = {
    title: "Loans · Sign on NeSL",
    figma: { portal: "476:231547", confirm: "476:231762" },
    timers: [],
    leave() { this.timers.forEach(clearTimeout); this.timers = []; OPL.dscreens.kfs.leave(); },

    render(page) {
      this.leave();
      const apps = OPL.apps.currentApps();
      this.id = OPL.state.get().app || (apps.find((a) => a.status === "sign" || a.status === "kfs") || {}).id || "pick-citi";
      this.page = page;
      const step = Number(OPL.state.get().step) || 0;
      if (step >= STEPS.length) return this.confirm(true);
      OPL.apps.setStatus(this.id, "sign");
      // backdrop: the KFS, read to the end, consent ticked (as in every NeSL frame)
      OPL.dscreens.kfs.render(page, { read: true });
      const layer = document.createElement("div");
      layer.className = "d-modal-layer d-nesl";
      layer.innerHTML = `<div class="d-scrim"></div><section class="d-nesl__win" role="dialog" aria-label="NeSL Digital Document Execution" data-win></section>`;
      page.querySelector(".d-app").appendChild(layer);
      void layer.offsetWidth; layer.classList.add("is-open");
      this.win = layer.querySelector("[data-win]");
      STEPS.forEach((s) => { const i = new Image(); i.src = src(s.id); });
      this.show(step);
      layer.addEventListener("click", (e) => {
        if (e.target.closest("[data-nesl-next]")) return this.show(this.step + 1);
        if (e.target.closest("[data-nesl-cancel]")) return this.cancel();
        const hit = layer.querySelector(".d-nesl__view:last-child [data-nesl-next]");
        if (hit && document.documentElement.dataset.hotspots !== "off") { hit.classList.remove("hotspot-flash"); void hit.offsetWidth; hit.classList.add("hotspot-flash"); }
      });
      // reading the agreement: a scroll over the document moves to its end (I AGREE)
      layer.addEventListener("wheel", (e) => {
        if (STEPS[this.step] && STEPS[this.step].scrollToNext && e.deltaY > 0) { e.preventDefault(); this.show(this.step + 1); }
      }, { passive: false });
    },

    show(step) {
      this.step = step;
      if (step >= STEPS.length) return this.confirm(false);
      const s = STEPS[step];
      this.win.style.width = `${s.w}px`;
      this.win.style.height = `${s.h}px`;
      const view = document.createElement("div");
      view.className = "d-nesl__view";
      view.innerHTML = `<img src="${src(s.id)}" width="${s.w}" height="${s.h}" alt="NeSL: ${s.id}" draggable="false">
        ${s.next ? `<button class="nesl-hit ${s.scrollToNext ? "nesl-hit--quiet" : ""}" style="${box(s, s.next)}" data-nesl-next aria-label="${s.scrollToNext ? "Read the agreement" : "Continue"}"></button>` : ""}
        ${s.cancel ? `<button class="nesl-hit nesl-hit--quiet" style="${box(s, s.cancel)}" data-nesl-cancel aria-label="Cancel"></button>` : ""}`;
      const old = this.win.firstElementChild;
      this.win.appendChild(view);
      if (old) { old.classList.add("is-out"); setTimeout(() => old.remove(), D.motionOff() ? 0 : 220); }
    },

    cancel() {
      OPL.apps.setStatus(this.id, "sign");
      OPL.go("application", { app: this.id, step: null }, { replace: true });
    },

    // 476:231762 — "Confirming your signature" in the main panel, then Signed + milestone
    confirm(park) {
      const c = OPL.data.nesl.confirm;
      this.page.innerHTML = D.shell({
        nav: "loans", title: "", tab: null,
        body: html`<div class="d-confirm">
          <img class="nesl-confirm__spin" src="assets/icons/spinner.svg" width="64" height="64" alt="">
          <h1>${c.title}</h1><p>${c.sub}</p><small>${c.foot}</small>
        </div>`,
      });
      D.mountShell(this.page);
      if (park) return;
      this.timers.push(setTimeout(() => {
        if (!this.page.isConnected) return;
        OPL.apps.setStatus(this.id, "signed");
        OPL.screens.application.celebrate = true;
        OPL.go("application", { app: this.id, step: null }, { replace: true });
      }, D.motionOff() ? 400 : c.wait));
    },
  };
})();

;
